const posts = $input.all().map(i => i.json);
const results = [];

for (const post of posts) {
  let title = post.title.rendered
    .replace(/<[^>]+>/g, '')
    .replace(/&#8217;/g, "'")
    .replace(/&#8211;/g, "-")
    .replace(/&amp;/g, "&")
    .replace(/&rsquo;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&rdquo;/g, '"')
    .replace(/&ldquo;/g, '"');

  const date = post.date.substring(0, 10);

  let text = post.content.rendered;
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/\.[\w-][\s\S]*?\{[\s\S]*?\}/g, '');
  text = text.replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gs, '\n\n$1\n\n');
  text = text.replace(/<p[^>]*>(.*?)<\/p>/gs, '$1\n\n');
  text = text.replace(/<br\s*\/?>/g, '\n');
  text = text.replace(/<li[^>]*>(.*?)<\/li>/gs, '  - $1\n');
  text = text.replace(/<a[^>]*>(.*?)<\/a>/gs, '$1');
  text = text.replace(/<[^>]+>/g, '');
  text = text.replace(/&#(\d+);/g, (m, n) => String.fromCharCode(n));
  text = text.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&rsquo;/g, "'").replace(/&nbsp;/g, ' ');
  text = text.replace(/\n{3,}/g, '\n\n').trim();

  const header = `Source: ${post.link}\nDate: ${date}\n\n${title}\n${'='.repeat(Math.min(title.length, 60))}\n\n`;
  const searchTerm = `${date} - ${title.substring(0, 30).replace(/'/g, "\\'")}`;

  results.push({
    json: {
      title,
      date,
      searchQuery: `name contains '${searchTerm}' and mimeType = 'application/vnd.google-apps.document' and trashed = false`,
      fullText: header + text
    }
  });
}

return results;

const items = $input.all();
const parseItems = $('Parse All Posts').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const files = items[i].json.files || [];
  if (files.length === 0) continue;

  const docId = files[0].id;
  const docName = files[0].name;
  const fullText = parseItems[i].json.fullText;
  const title = parseItems[i].json.title;

  results.push({
    json: {
      docId,
      docName,
      title,
      fullText
    }
  });
}

return results.length > 0 ? results : [{ json: { skip: true } }];

const items = $input.all();
const matchItems = $('Match + Filter Found').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const content = items[i].json.content || '';
  // Doc is empty if content is just whitespace/newline (< 10 chars)
  if (content.trim().length < 10) {
    results.push({
      json: {
        docId: matchItems[i].json.docId,
        title: matchItems[i].json.title,
        fullText: matchItems[i].json.fullText
      }
    });
  }
}

return results.length > 0 ? results : [{ json: { skip: true } }];
